// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Owned} from "../src/Owned.sol";

contract InvMutTest is Test {
    Owned c;
    function setUp() public { c = new Owned(); }
    function testFuzz_property(address newOwner) public {
        vm.assume(newOwner != address(0));
        vm.prank(c.owner());
        (bool ok, bytes memory data) = address(c).call(abi.encodeWithSelector(c.setOwner.selector, newOwner));
        bool ret = ok && abi.decode(data, (bool));
        assertTrue(ok && ret && c.owner() == newOwner, "successful setOwner must return true and set owner");
    }
}
